<script setup lang="ts">
import { ref } from 'vue';
import { getImportAudit } from '../../api/imports.ts';
import type { MappingReferenceResponse } from '../../api/contracts.ts';
import { formatDate, formatInteger } from '../../shared/format.ts';
const openState=ref(false);const loading=ref(false);const error=ref('');const data=ref<MappingReferenceResponse|null>(null);
async function open(){openState.value=true;loading.value=true;error.value='';try{data.value=await getImportAudit()}catch(caught){error.value=caught instanceof Error?caught.message:'Could not load import history'}finally{loading.value=false}}
function close(){openState.value=false}defineExpose({open});
</script>
<template><Teleport to="body"><div v-if="openState" class="merchant-manager-backdrop" @mousedown.self="close"><section class="import-audit-modal" role="dialog" aria-modal="true" aria-labelledby="import-audit-title"><button type="button" class="transactions-modal-close" aria-label="Close import history" @click="close">×</button><header><p>Data management</p><h2 id="import-audit-title">Import history</h2><span>Statement coverage, inserted rows and duplicates recorded by the local database.</span></header><div v-if="loading" class="panel-state">Loading import history…</div><div v-else-if="error" class="panel-state error-state"><span>{{ error }}</span><button type="button" @click="open">Try again</button></div><div v-else class="import-audit-body"><div class="import-audit-summary"><div><strong>{{ formatInteger(data?.recent_imports.reduce((sum,item)=>sum+item.inserted_rows,0)||0) }}</strong><span>recently inserted rows</span></div><div><strong>{{ formatInteger(data?.recent_imports.reduce((sum,item)=>sum+item.duplicate_rows,0)||0) }}</strong><span>duplicates prevented</span></div><div><strong>{{ formatInteger(data?.summary.needs_review||0) }}</strong><span>merchants need review</span></div></div><div class="import-table-wrap"><table><thead><tr><th>File</th><th>Provider / cards</th><th>Statement period</th><th>Coverage</th><th>Result</th></tr></thead><tbody><tr v-for="item in data?.recent_imports||[]" :key="item.id"><td><strong>{{ item.original_name }}</strong><small>Imported {{ formatDate(item.imported_at.slice(0,10)) }}</small></td><td>{{ item.provider.toUpperCase() }}<small>{{ item.coverage.length?item.coverage.map(part=>`•• ${part.card_last4}`).join(' · '):(item.card_last4?`•• ${item.card_last4}`:'—') }}</small></td><td>{{ item.statement_range||'Unavailable' }}</td><td><span v-for="part in item.coverage" :key="part.card_last4">{{ part.purchase_date_from&&part.purchase_date_to?`${formatDate(part.purchase_date_from)}–${formatDate(part.purchase_date_to)}`:'—' }}</span></td><td><i>{{ item.status.replaceAll('_',' ') }}</i><small>{{ item.inserted_rows }} inserted · {{ item.duplicate_rows }} duplicates · {{ item.coverage.reduce((sum,part)=>sum+(part.pending_rows||0),0) }} pending</small></td></tr><tr v-if="!data?.recent_imports.length"><td colspan="5" class="transactions-empty">No statement imports recorded.</td></tr></tbody></table></div></div></section></div></Teleport></template>
